def count_derangements(n: int) -> int:
    """Permutations of n items with no fixed point, by brute-force enumeration (small n only)."""
    items: list[int] = []
    for i in range(n):
        items.append(i)
    total: int = 0
    while True:
        fixed: bool = False
        for i in range(n):
            if items[i] == i:
                fixed = True
                break
        if not fixed:
            total += 1
        if not next_permutation(items):
            break
    return total

