def next_permutation(items: list[int]) -> bool:

    i: int = len(items) - 2
    while i >= 0 and items[i] >= items[i + 1]:
        i -= 1
    if i < 0:
        return False
    j: int = len(items) - 1
    while items[j] <= items[i]:
        j -= 1
    tmp: int = items[i]
    items[i] = items[j]
    items[j] = tmp
    lo: int = i + 1
    hi: int = len(items) - 1
    while lo < hi:
        tmp = items[lo]
        items[lo] = items[hi]
        items[hi] = tmp
        lo += 1
        hi -= 1
    return True

